def blobs_world(h, min_px=50, near_xy=None):
    bl = gold_blobs(h, min_px=min_px)
    return bl

def report(tag=""):
    h = head()
    b = board(h)
    cs = cells(b)
    bl = gold_blobs(h)
    rings, held, crosses = [], [], []
    for d in bl:
        w = np.array(d["mean_world"]); zmax = d["zmax"]; area = d["area"]
        if zmax > 0.83:
            held.append(d)
        elif d["uv"][1] < 190 and w[1] > 0.15 and area > 60:
            crosses.append(d)
        elif area > 60:
            rings.append(d)
    def show(name, lst):
        print(" ", name, len(lst))
        for d in lst:
            print("    uv", np.round(d["uv"], 1).tolist(), "area", d["area"],
                  "world", np.round(d["mean_world"], 4).tolist(), "zmax", round(d["zmax"], 4))
    show("held", held); show("crosses(far)", crosses); show("rings/board", rings)
    print("board top_z", round(b["top_z"], 4))
    return dict(head=h, board=b, cells=cs, rings=rings, held=held, crosses=crosses)

def far_crosses(h, min_px=40):
    out = []
    for d in gold_blobs(h, min_px=min_px):
        w = np.array(d["mean_world"])
        if w[1] > 0.15 and 0.768 <= d["zmax"] <= 0.782:
            out.append(d)
    return out

def white_arm_lowest_v(h):
    rgb = h["rgb"]
    m = (rgb[..., 0] > 195) & (rgb[..., 1] > 195) & (rgb[..., 2] > 195)
    from scipy import ndimage as ndi
    lab = measure.label(m, connectivity=2)
    best = None
    for p in measure.regionprops(lab):
        if p.area < 300:
            continue
        if best is None or p.area > best.area:
            best = p
    if best is None:
        return None
    ys, xs = np.nonzero(lab == best.label)
    return dict(area=int(best.area), v_max=int(ys.max()), v_min=int(ys.min()),
                u_min=int(xs.min()), u_max=int(xs.max()))

